/**
 * The installed Thai dictionary's headwords and parts of speech (dictionary-words-data.ts, generated by
 * scripts/thai-words-build.mts from Wiktionary via kaikki.org, CC BY-SA 4.0). Thai does not inflect, so a headword is its own
 * lemma: a word the course list lacks but the dictionary has gets the dictionary's parts of speech as readings, below any
 * course-list reading and with no gloss of its own (the card asks the dictionary for the meaning). Parsed on first use.
 */
import { THAI_DICTIONARY_ID, THAI_DICTIONARY_WORDS } from './dictionary-words-data';

export { THAI_DICTIONARY_ID };

const POS_OF: Readonly<Record<string, string>> = {
  N: 'NOUN', V: 'VERB', A: 'ADJ', P: 'PROPN', D: 'ADV', I: 'INTJ', C: 'CLF', M: 'NUM', R: 'PRON', S: 'ADP', J: 'CONJ', T: 'PART', E: 'DET',
};

let words: Map<string, readonly string[]> | undefined;
function table(): Map<string, readonly string[]> {
  if (words) return words;
  words = new Map();
  for (const line of THAI_DICTIONARY_WORDS.split('\n')) {
    const tab = line.indexOf('\t');
    if (tab <= 0) continue;
    words.set(line.slice(0, tab), [...line.slice(tab + 1)].map((c) => POS_OF[c]).filter(Boolean));
  }
  return words;
}

/** The dictionary's parts of speech for a normalized Thai form, its first first; undefined when it is not a headword. */
export const dictionaryPartsOfSpeech = (normalized: string): readonly string[] | undefined => table().get(normalized);
export const isDictionaryWord = (normalized: string): boolean => table().has(normalized);
export const dictionaryWordCount = (): number => table().size;
